$cmd=[PHP_BINARY,$work.'/worker.php','reports.php','GET','{}','Staff','type=loss_history&download=1'];$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fclose($pipes[0]);$csv=stream_get_contents($pipes[1]);fclose($pipes[1]);$errors=stream_get_contents($pipes[2]);fclose($pipes[2]);proc_close($p);
